/**
 * HL7v2-to-FHIR code table mappings, generated directly from the official v2-to-FHIR IG's
 * ConceptMap resources (https://hl7.org/fhir/uv/v2mappings/artifacts.html, "Vocabulary/Table
 * Mappings" section) — fetched and transformed programmatically rather than hand-transcribed,
 * to avoid transcription errors across the IG's ~70 vocabulary tables. Do not hand-edit
 * individual entries; regenerate from the IG if it publishes an update. Source codes the IG
 * itself marks as unmapped (no target code) are omitted here rather than kept with a null
 * code, so a lookup miss always means "not in this table," never "mapped to nothing."
 *
 * Keyed by the IG's own ConceptMap id (e.g. "table-hl70001-to-administrative-gender") since
 * several HL7v2 tables map to more than one FHIR target (e.g. HL70004 maps to both
 * Encounter.status and v3-ActCode) — the id disambiguates which target a given segment field
 * actually needs.
 */

export interface VocabularyMapping {
  code: string;
  display: string | undefined;
  system: string | undefined;
}

