/** Looks up the FHIR mapping for an HL7v2 code in a given IG vocabulary table (see VOCABULARY's keys). Returns undefined if the table or code is unknown, or if the IG marks that code as unmapped. */
export function lookupVocabulary(tableId: string, hl7Code: string | undefined): VocabularyMapping | undefined {
  if (!hl7Code) return undefined;
  return VOCABULARY[tableId]?.[hl7Code];
}

/**
 * Reverse lookup: the first HL7v2 code (in the IG's own table order) that maps to the given
 * FHIR code in a table. Not necessarily unique — several v2 codes commonly map to the same
 * FHIR code (e.g. HL70001's "A" and "N" both map to "other", same as "O") — callers that need
 * a specific reverse code for round-tripping should pass the same code that was used forward,
 * not rely on this picking the "right" one out of several valid reverse candidates.
 */
export function reverseLookupVocabulary(tableId: string, fhirCode: string | undefined): string | undefined {
  if (!fhirCode) return undefined;
  const table = VOCABULARY[tableId];
  if (!table) return undefined;
  for (const [hl7Code, mapping] of Object.entries(table)) {
    if (mapping.code === fhirCode) return hl7Code;
  }
  return undefined;
}
